   19	// A Message is one notification.
   20	type Message struct {
   21		To      *store.User
   22		Subject string
   23		Body    string
   24	}
   25	
   26	// A Sender delivers messages over one channel.
   27	type Sender interface {
   28		Send(ctx context.Context, m Message) error
   29	}
   30	
   31	// channels lists the channel names users may choose.
