   34	// ValidChannel reports whether name is a channel users may choose.
   35	func ValidChannel(name string) bool {
   36		return slices.Contains(channels, name)
   37	}
   38	
   39	// Dispatcher sends due reminders.
   40	type Dispatcher struct {
   41		store   *store.Store
   42		senders map[string]Sender
   43		log     *slog.Logger
   44		now     func() time.Time
   45	
   46		mu      sync.Mutex
